{"command": "python3 - <<'PY'
with open("/tmp/color20.txt","rb") as f:
    data=f.read()
lines=data.split(b"\r\n")
import re
for idx in range(1,21):
    l=lines[idx].decode('utf-8')
    art_part=l.split("seq=")[0]
    pat2=re.compile(r'(?:\x1b\[(\d+);1m#\x1b\[0;22m)|([\. ])')
    colors=[]
    stripped=""
    for m in pat2.finditer(art_part):
        if m.group(1):
            colors.append(m.group(1))
            stripped+="#"
        else:
            stripped+=m.group(2)
    mp={'90':'K','97':'W','93':'Y','91':'R'}
    annotated=""
    ci=0
    for ch in stripped:
        if ch=="#":
            annotated+=mp.get(colors[ci], "?")
            ci+=1
        else:
            annotated+=ch
    print(f"{idx-1:2d} {repr(stripped)}")
    print(f"   {repr(annotated)} colors={colors}")
PY
"}

