{"command": "cat <<'GO' > /tmp/testping.go
package main

import (
	"fmt"
	"net"
	"time"
)

func main() {
	// try unprivileged via ip4:icmp
	c, err := net.ListenPacket("ip4:icmp", "0.0.0.0")
	fmt.Printf("ip4:icmp listen err=%v conn=%v\n", err, c)
	if err == nil { c.Close() }
	c2, err := net.ListenPacket("udp", "0.0.0.0")
	fmt.Printf("udp listen err=%v conn=%v local=%v\n", err, c2, func()string{if(c2!=nil){return c2.LocalAddr().String()}; return ""}())
	if err == nil { c2.Close() }
	// try dial udp to 127.0.0.1:0
	d, err := net.Dial("udp", "0.0.0.0:0", "127.0.0.1:0")
	fmt.Printf("dial udp 127.0.0.1:0 err=%v\n", err)
	if err == nil {
		d.SetDeadline(time.Now().Add(2*time.Second))
		n, err := d.Write([]byte("hello"))
		fmt.Printf("write n=%d err=%v\n", n, err)
		d.Close()
	}
	// try resolve
	addr, err := net.ResolveIPAddr("ip", "localhost")
	fmt.Printf("resolve localhost: %v err=%v\n", addr, err)
	addr2, err := net.ResolveIPAddr("ip", "999.999.999.999")
	fmt.Printf("resolve 999...: %v err=%v\n", addr2, err)
	addr3, err := net.ResolveIPAddr("ip", "")
	fmt.Printf("resolve empty: %v err=%v\n", addr3, err)
	addr4, err := net.ResolveIPAddr("ip", "foo.invalid")
	fmt.Printf("resolve foo.invalid: %v err=%v\n", addr4, err)
}
GO
go run /tmp/testping.go 2>&1
"}

