cat <<'GO' > /tmp/testudp.go
package main

import (
	"fmt"
	"net"
	"time"
)

func main() {
	c, err := net.ListenPacket("udp", "0.0.0.0:0")
	fmt.Printf("udp listen err=%v local=%v\n", err, func()string{if(err==nil){return c.LocalAddr().String()};return ""}())
	if err != nil { return }
	defer c.Close()
	fmt.Printf("local addr type %T\n", c.LocalAddr())
	// try to dial/write icmp via udp?
	// In go-ping unprivileged, it writes ICMP packet to udp conn with addr?
	// Let's try writing raw bytes to 127.0.0.1:0
	dst, _ := net.ResolveUDPAddr("udp", "127.0.0.1:0")
	n, err := c.WriteTo([]byte("hello world test payload 123456"), dst)
	fmt.Printf("WriteTo n=%d err=%v\n", n, err)
	c.SetDeadline(time.Now().Add(2*time.Second))
	buf := make([]byte, 1500)
	n, addr, err := c.ReadFrom(buf)
	fmt.Printf("ReadFrom n=%d addr=%v err=%v data=%q\n", n, addr, err, string(buf[:n]))
}
GO
go run /tmp/testudp.go 2>&1
"}

