package main

import (
	"fmt"
	"syscall"
)

func main() {
	fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	fmt.Printf("SOCK_DGRAM ICMP fd=%d err=%v\n", fd, err)
	if err == nil {
		syscall.Close(fd)
	}
	fd2, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_RAW, syscall.IPPROTO_ICMP)
	fmt.Printf("SOCK_RAW ICMP fd=%d err=%v\n", fd2, err)
	if err == nil {
		syscall.Close(fd2)
	}
	fd3, err := syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, 58) // 58 = ICMPv6
	fmt.Printf("SOCK_DGRAM ICMPv6 fd=%d err=%v\n", fd3, err)
	if err == nil {
		syscall.Close(fd3)
	}
}
GO
go run /tmp/testraw.go 2>&1
"}

