{"command": "cat <<'GO' > /tmp/test_udp_err.go
package main

import (
	"fmt"
	"net"
)

func main() {
	for _, network := range []string{"udp", "udp4", "udp6"} {
		for _, laddr := range []string{"0.0.0.0:0", "[::]:0"} {
			c, err := net.ListenPacket(network, laddr)
			if err != nil {
				fmt.Printf("ListenPacket(%q,%q) err=%v\n", network, laddr, err)
				continue
			}
			fmt.Printf("ListenPacket(%q,%q) ok local=%v\n", network, laddr, c.LocalAddr())
			// try write to unreachable
			var dst net.Addr
			if network == "udp6" {
				dst, _ = net.ResolveUDPAddr(network, "[2001:db8::1]:0")
			} else {
				dst, _ = net.ResolveUDPAddr(network, "10.0.0.5:0")
			}
			_, err = c.WriteTo([]byte("hello"), dst)
			fmt.Printf("  WriteTo err=%v\n", err)
			c.Close()
		}
	}
	// privileged attempt
	c, err := net.ListenPacket("ip4:icmp", "0.0.0.0")
	fmt.Printf("ListenPacket ip4:icmp err=%v\n", err)
	if c != nil { c.Close() }
	c, err = net.ListenPacket("ip6:ipv6-icmp", "::")
	fmt.Printf("ListenPacket ip6:ipv6-icmp err=%v\n", err)
	if c != nil { c.Close() }
}
GO
go run /tmp/test_udp_err.go 2>&1
"}

