{"command": "cat <<'GO' > /tmp/test_udp2.go
package main

import (
	"fmt"
	"net"
)

func main() {
	c, _ := net.ListenPacket("udp4", "0.0.0.0:0")
	fmt.Printf("local %v\n", c.LocalAddr())
	for _, port := range []string{"0", "80", "12345"} {
		dst, _ := net.ResolveUDPAddr("udp4", "10.0.0.5:"+port)
		_, err := c.WriteTo([]byte("hello"), dst)
		fmt.Printf("WriteTo port %s err=%v\n", port, err)
	}
	c.Close()
	c2, _ := net.ListenPacket("udp", "0.0.0.0:0")
	fmt.Printf("udp local %v\n", c2.LocalAddr())
	dst, _ := net.ResolveUDPAddr("udp", "10.0.0.5:80")
	_, err := c2.WriteTo([]byte("hello"), dst)
	fmt.Printf("udp WriteTo 10.0.0.5:80 err=%v\n", err)
