{"command": "cat <<'GO' > /tmp/test_icmp2.go
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"syscall"
	"time"
)

func checksum(b []byte) uint16 {
	sum := 0
	for i := 0; i < len(b)-1; i += 2 {
		sum += int(binary.BigEndian.Uint16(b[i:]))
	}
	if len(b)%2 == 1 {
		sum += int(b[len(b)-1]) << 8
	}
	sum = (sum >> 16) + (sum & 0xffff)
	sum += (sum >> 16)
	return uint16(^sum)
}

func main() {
	fd, _ := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	defer syscall.Close(fd)
	syscall.Bind(fd, &syscall.SockaddrInet4{Port: 0})
	sa, _ := syscall.Getsockname(fd)
	fmt.Printf("getsockname %v\n", sa)
	// build ICMP echo
	pkt := make([]byte, 40) // 8 header + 32 payload?
	pkt[0] = 8 // echo request
	pkt[1] = 0
	// id, seq
	binary.BigEndian.PutUint16(pkt[4:6], 1234)
	binary.BigEndian.PutUint16(pkt[6:8], 0)
	for i := 8; i < len(pkt); i++ {
		pkt[i] = byte(i)
	}
	cs := checksum(pkt)
	binary.BigEndian.PutUint16(pkt[2:4], cs)
	fmt.Printf("pkt %v cs %x\n", pkt[:10], cs)
	dst := &syscall.SockaddrInet4{Port: 0}
	copy(dst.Addr[:], net.ParseIP("127.0.0.1").To4())
	err := syscall.Sendto(fd, pkt, 0, dst)
	fmt.Printf("sendto 127.0.0.1 err=%v\n", err)
	if err != nil { return }
	// set timeout and recv
	tv := syscall.NsecToTimeval((500 * time.Millisecond).Nanoseconds())
	syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)
	buf := make([]byte, 1500)
	n, from, err := syscall.Recvfrom(fd, buf, 0)
	fmt.Printf("recv n=%d from=%v err=%v data=%v\n", n, from, err, buf[:n])
	// try unreachable
	dst2 := &syscall.SockaddrInet4{Port: 0}
	copy(dst2.Addr[:], net.ParseIP("10.0.0.5").To4())
	err = syscall.Sendto(fd, pkt, 0, dst2)
	fmt.Printf("sendto 10.0.0.5 err=%v\n", err)
}
GO
go run /tmp/test_icmp2.go 2>&1
"}

