package main

import (
	"fmt"
)

func isOption(s string) bool {
	if s == "--" || s == "-" || s == "" {
		return false
	}
	if len(s) >= 2 && s[0] == '-' {
		// check negative number: - + digit
		if s[1] >= '0' && s[1] <= '9' {
			// Could be -5 or -5x? For -5x, should it be option or value?
			// Let's treat any - + digit as NOT option (value), to allow parsing attempt
			return false
		}
		return true
	}
	return false
}

func main() {
	for _, s := range []string{"-h", "-V", "-P", "-c", "-x", "-5", "-5x", "--privilege", "--", "-", "", "--5", "-"} {
		fmt.Printf("%q isOption=%v\n", s, isOption(s))
	}
}
