{"command": "cat <<'GO' >> main.go

func checksum(b []byte) uint16 {
	sum := 0
	for i := 0; i < len(b)-1; i += 2 {
		sum += int(binary.BigEndian.Uint16(b[i:]))
	}
	if len(b)%2 == 1 {
		sum += int(b[len(b)-1]) << 8
	}
	sum = (sum >> 16) + (sum & 0xffff)
	sum += (sum >> 16)
	return uint16(^sum)
}

func printHeader(host, ip string) {
	line := fmt.Sprintf("PING %s (%s) type `Ctrl-C` to abort", host, ip)
	if useColor {
		fmt.Fprintf(os.Stdout, "\x1b[97;1m%s\n", line)
		fmt.Fprintf(os.Stdout, "\x1b[0m")
	} else {
		fmt.Fprintln(os.Stdout, line)
	}
}

func printPingLine(seq int, ip string, ttl int, rtt time.Duration, frameIdx int) {
	art := renderArt(frameIdx)
	seqStr := sprint("93", strconv.Itoa(seq))
	bytesStr := sprint("94", "32")
	ipStr := sprint("37", ip)
	ttlStr := sprint("96", strconv.Itoa(ttl))
	timeStr := sprint("95", rtt.String())
	// format: <art> seq=<seq> <bytes>bytes from <ip>: ttl=<ttl> time=<time>
	fmt.Fprintf(os.Stdout, "%s seq=%s %sbytes from %s: ttl=%s time=%s\n", art, seqStr, bytesStr, ipStr, ttlStr, timeStr)
}

func printStats(host string, transmitted, received int, loss float64, min, avg, max, stddev time.Duration) {
	// blank line + separator
	sep := fmt.Sprintf("───────── %s ping statistics ─────────", host)
	if useColor {
		fmt.Fprintf(os.Stdout, "\x1b[37;1m\n")
		fmt.Fprintln(os.Stdout, sep)
		fmt.Fprintf(os.Stdout, "\x1b[0m")
	} else {
		fmt.Fprintln(os.Stdout, "")
		fmt.Fprintln(os.Stdout, sep)
	}
	// PACKET STATISTICS line
	var lossStr string
	if math.IsNaN(loss) {
		lossStr = "NaN%"
	} else {
		lossStr = fmt.Sprintf("%v%%", loss)
	}
	// need to color parts
	packetLabel := sprint("97", "PACKET STATISTICS")
	transStr := sprint("94", strconv.Itoa(transmitted))
	recvStr := sprint("92", strconv.Itoa(received))
	// loss includes % inside color
	lossColored := sprint("91", lossStr)
	fmt.Fprintf(os.Stdout, "%s: %s transmitted => %s received (%s loss)\n", packetLabel, transStr, recvStr, lossColored)
	roundLabel := sprint("97", "ROUND TRIP")
	minStr := sprint("94", min.String())
	avgStr := sprint("96", avg.String())
	maxStr := sprint("92", max.String())
	stdStr := sprint("35", stddev.String())
	fmt.Fprintf(os.Stdout, "%s: min=%s avg=%s max=%s stddev=%s\n", roundLabel, minStr, avgStr, maxStr, stdStr)
}

